\label{lmm:normal}
Let $\nu_p:=p+\beta_p$ and set $s:=\big(\frac{\Delta}{L_p}\big)^{\frac1\nu},
\widehat L_r:=\frac{L_r s^{r+\beta_r}}{\Delta}
\quad(r\in\mathcal I),
\widehat{\mathbf L}:=(\widehat L_r)_{r\in\mathcal I}.$








Then $\widehat L_p=1$, and for any of the oracle models defined
above, $*\in\{\mathrm{det},\mathrm{rand}\}$, and $\varepsilon>0$,
\[
\mathcal C_*^{(\mathcal I,\boldsymbol\beta)}
(\varepsilon;\mathbf L,\Delta,\mathcal O)
=
\mathcal C_*^{(\mathcal I,\boldsymbol\beta)}
\big(
    \tfrac{\varepsilon}
    {L_p^{1/\nu_p}\Delta^{(\nu_p-1)/\nu_p}};
    \widehat{\mathbf L},1,\mathcal O
\big).
\]

\label{thm:randomized-derivative-lower-bound}
There exists a constant $c_p>0$, depending only on $p$, such that
for every
$0<\varepsilon\le
c_p\min_{r\in\mathcal I}
L_r^{\frac{1}{\nu_r}}
\Delta^{\frac{\nu_r-1}{\nu_r}}$,
\[
\mathcal C_{\mathrm{rand}}^{(\mathcal I,\boldsymbol\beta)}
(\varepsilon;\mathbf L,\Delta,\mathcal O^{1:p})
\ge
c_p
\min_{r\in\mathcal I}
L_r^{\frac{1}{\nu_r}}
\Delta^{\frac{\nu_r-1}{\nu_r}}
\varepsilon^{-1}.
\]

\label{thm:deterministic-derivative-jet-lower}
There exists a constant $c_{p,\boldsymbol\beta}>0$,
depending only on $p$ and $\boldsymbol\beta$, such that,
for every $L_1,\ldots,L_p,\Delta>0$ and
$0<\varepsilon\le c_{p,\boldsymbol\beta}
\min_{1\le r\le p}
L_r^{\frac{1}{\nu_r}}\Delta^{\frac{\nu_r-1}{\nu_r}}$,
\[
\mathcal C_{\mathrm{det}}^{(\mathcal I,\boldsymbol\beta)}
(\varepsilon;\mathbf L,\Delta,\mathcal O^{1:p})
\ge c_{p,\boldsymbol\beta}
\min_{1\le r\le p}
L_r^{\frac{1}{\nu_r-1}}\Delta
\varepsilon^{-\frac{\nu_r}{\nu_r-1}}.
\]

\label{thm:randomized-derivative-upper-bound}
Let $\nu_r:=r+\beta_r$ for $r\in\mathcal I$.
There exists a constant $C_{\mathcal I,\boldsymbol\beta}>0$,
depending only on $\mathcal I$ and $\boldsymbol\beta$, such that,
for every
$0<\varepsilon\le
\min_{r\in\mathcal I}
L_r^{\frac{1}{\nu_r}}
\Delta^{\frac{\nu_r-1}{\nu_r}}$,
the following bounds hold:
\begin{align*}
\mathcal C_{\mathrm{det}}^{(\mathcal I,\boldsymbol\beta)}
(\varepsilon;\mathbf L,\Delta,\mathcal O^1)
&\le
C_{\mathcal I,\boldsymbol\beta}
\min_{r\in\mathcal I}
L_r^{\frac{1}{\nu_r-1}}\Delta
\varepsilon^{-\frac{\nu_r}{\nu_r-1}},\\
\mathcal C_{\mathrm{rand}}^{(\mathcal I,\boldsymbol\beta)}
(\varepsilon;\mathbf L,\Delta,\mathcal O^1)
&\le
C_{\mathcal I,\boldsymbol\beta}
\min_{r\in\mathcal I}
L_r^{\frac{1}{\nu_r}}
\Delta^{\frac{\nu_r-1}{\nu_r}}
\varepsilon^{-1}.
\end{align*}

\label{thm:randomized-full-jet-lower-bound}
Let $\mathcal I:=\{1,\ldots,p\}$ and $\nu_r:=r+\beta_r$.
There exists a constant $c_{p,\boldsymbol\beta}\in(0,1)$,
depending only on $p$ and $\boldsymbol\beta$, such that,
for every $L_1,\ldots,L_p,\Delta>0$ and
$0<\varepsilon\le c_{p,\boldsymbol\beta}
\min_{1\le r\le p}
L_r^{\frac1{\nu_r}}\Delta^{\frac{\nu_r-1}{\nu_r}}$,
\[
\mathcal C_{\mathrm{rand}}^{(\mathcal I,\boldsymbol\beta)}
(\varepsilon;\mathbf L,\Delta,\mathcal O^{0:p})
\ge c_{p,\boldsymbol\beta}
\log\big(
{
\displaystyle\min_{1\le r\le p}
L_r^{\frac1{\nu_r}}\Delta^{\frac{\nu_r-1}{\nu_r}}
}{\varepsilon^{-1}}
\big).
\]

\label{thm:deterministic-zeroth-order-upper}
There exists a constant $C_{\mathcal I,\boldsymbol\beta}>0$, depending only
on $\mathcal I$ and $\boldsymbol\beta$, such that, for every
$\mathbf L\in(0,\infty)^{\mathcal I}$, $\Delta>0$, and $\varepsilon>0$,
\[
\mathcal C_{\mathrm{det}}^{(\mathcal I,\boldsymbol\beta)}
(\varepsilon;\mathbf L,\Delta,\mathcal O^0)
\le
C_{\mathcal I,\boldsymbol\beta}
\big(
1+\log_+\big(
\min_{r\in\mathcal I}
L_r^{\frac{1}{\nu_r}}
\Delta^{\frac{\nu_r-1}{\nu_r}}
\varepsilon^{-1}
\big)
\big),
\]
where $\log_+(t):=\max\{\log t,0\}$.
